-- Schema 8 exported from be4af80 using a new fixture database.
-- No device data or credentials. Only this authorized upgrade is supported.
CREATE TABLE "agent_plans" ("id" TEXT NOT NULL, "revision" INTEGER NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "source_run_id" TEXT NOT NULL, "source_message_id" TEXT NOT NULL, "title" TEXT NOT NULL, "steps_json" TEXT NOT NULL, "status" TEXT NOT NULL, "execution_run_id" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id", "revision"));
CREATE TABLE "agent_runs" ("id" TEXT NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "assistant_id" TEXT NULL, "input_message_id" TEXT NOT NULL, "current_message_id" TEXT NULL, "active_tool_call_id" TEXT NULL, "configuration_json" TEXT NOT NULL, "status" TEXT NOT NULL, "finish_reason" TEXT NULL, "turn_count" INTEGER NOT NULL DEFAULT 0, "model_attempt_count" INTEGER NOT NULL DEFAULT 0, "max_turns" INTEGER NOT NULL, "created_at" INTEGER NOT NULL, "finished_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "assistants" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "system_prompt" TEXT NOT NULL DEFAULT '', "default_selection_json" TEXT NULL, "tool_policy_json" TEXT NOT NULL DEFAULT '{}', "memory_scope" TEXT NOT NULL DEFAULT 'disabled', "skill_ids_json" TEXT NOT NULL DEFAULT '[]', "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "attachments" ("id" TEXT NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "kind" TEXT NOT NULL, "name" TEXT NOT NULL, "mime_type" TEXT NOT NULL, "size" INTEGER NOT NULL, "local_path" TEXT NOT NULL, "sha256" TEXT NULL, "extracted_text_path" TEXT NULL, "extraction_error" TEXT NULL, "width" INTEGER NULL, "height" INTEGER NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "context_summaries" ("id" TEXT NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "run_id" TEXT NULL, "branch_end_id" TEXT NOT NULL, "covered_ids_json" TEXT NOT NULL, "fingerprint" TEXT NOT NULL, "source_model" TEXT NOT NULL, "version" INTEGER NOT NULL, "status" TEXT NOT NULL, "content" TEXT NOT NULL, "checkpoint_json" TEXT NOT NULL DEFAULT '{}', "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "conversations" ("workspace_id" TEXT NULL REFERENCES workspaces (id) ON DELETE SET NULL, "id" TEXT NOT NULL, "assistant_id" TEXT NULL, "title" TEXT NOT NULL, "current_message_id" TEXT NULL, "selection_json" TEXT NULL, "pinned" INTEGER NOT NULL DEFAULT 0 CHECK ("pinned" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "mcp_servers" ("id" TEXT NOT NULL, "profile_json" TEXT NOT NULL, "tools_json" TEXT NOT NULL DEFAULT '[]', "protocol_version" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "memory_entries" ("id" TEXT NOT NULL, "assistant_id" TEXT NULL, "source_message_id" TEXT NULL, "source_run_id" TEXT NULL, "content" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "created_at" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "messages" ("id" TEXT NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "parent_id" TEXT NULL, "run_id" TEXT NULL, "role" TEXT NOT NULL, "status" TEXT NOT NULL, "parts_json" TEXT NOT NULL DEFAULT '[]', "model_label" TEXT NULL, "thinking_duration_ms" INTEGER NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "model_requests" ("id" TEXT NOT NULL, "conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "run_id" TEXT NULL, "logical_turn" INTEGER NOT NULL, "attempt_index" INTEGER NOT NULL, "purpose" TEXT NOT NULL, "status" TEXT NOT NULL, "profile_id" TEXT NOT NULL, "protocol" TEXT NOT NULL, "requested_model_id" TEXT NOT NULL, "response_model_id" TEXT NULL, "assistant_message_id" TEXT NULL UNIQUE, "summary_id" TEXT NULL UNIQUE, "summary_job_id" TEXT NULL, "usage_json" TEXT NULL, "usage_revision" INTEGER NOT NULL DEFAULT 0, "usage_complete" INTEGER NOT NULL DEFAULT 0 CHECK ("usage_complete" IN (0, 1)), "context_json" TEXT NOT NULL, "origin_request_id" TEXT NULL, "is_inherited" INTEGER NOT NULL DEFAULT 0 CHECK ("is_inherited" IN (0, 1)), "error_code" TEXT NULL, "created_at" INTEGER NOT NULL, "started_at" INTEGER NULL, "finished_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "models" ("profile_id" TEXT NOT NULL REFERENCES provider_profiles (id) ON DELETE CASCADE, "model_id" TEXT NOT NULL, "display_name" TEXT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "supports_reasoning" INTEGER NOT NULL DEFAULT 0 CHECK ("supports_reasoning" IN (0, 1)), "supports_tools" INTEGER NOT NULL DEFAULT 0 CHECK ("supports_tools" IN (0, 1)), "supports_images" INTEGER NOT NULL DEFAULT 0 CHECK ("supports_images" IN (0, 1)), "context_window" INTEGER NULL, "max_output_tokens" INTEGER NULL, "temperature" REAL NULL, PRIMARY KEY ("profile_id", "model_id"));
CREATE TABLE "provider_profiles" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "protocol" TEXT NOT NULL, "base_url" TEXT NOT NULL, "requires_key" INTEGER NOT NULL DEFAULT 1 CHECK ("requires_key" IN (0, 1)), "preset_id" TEXT NOT NULL DEFAULT 'custom', "default_model" TEXT NULL, "compat_json" TEXT NULL, "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "runtime_environments" ("id" TEXT NOT NULL, "configuration_json" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "skill_installations" ("id" TEXT NOT NULL, "name" TEXT NOT NULL UNIQUE, "snapshot_json" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "deleting" INTEGER NOT NULL DEFAULT 0 CHECK ("deleting" IN (0, 1)), "installed_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "tool_calls" ("id" TEXT NOT NULL, "run_id" TEXT NOT NULL REFERENCES agent_runs (id) ON DELETE CASCADE, "assistant_message_id" TEXT NOT NULL, "result_message_id" TEXT NULL, "provider_call_id" TEXT NULL, "tool_name" TEXT NOT NULL, "arguments_json" TEXT NOT NULL, "source_json" TEXT NULL, "provider_data_json" TEXT NULL, "target" TEXT NULL, "channel" TEXT NOT NULL, "default_policy" TEXT NOT NULL, "status" TEXT NOT NULL, "decision" TEXT NULL, "confirmation_requested_at" INTEGER NULL, "confirmation_expires_at" INTEGER NULL, "decided_at" INTEGER NULL, "result" TEXT NULL, "artifacts_json" TEXT NOT NULL DEFAULT '[]', "error_code" TEXT NULL, "created_at" INTEGER NOT NULL, "started_at" INTEGER NULL, "finished_at" INTEGER NULL, PRIMARY KEY ("id"));
CREATE TABLE "usage_archives" ("conversation_id" TEXT NOT NULL REFERENCES conversations (id) ON DELETE CASCADE, "source_kind" TEXT NOT NULL, "source_id" TEXT NOT NULL, "report_json" TEXT NOT NULL, PRIMARY KEY ("conversation_id", "source_kind", "source_id"));
CREATE TABLE "workspace_copies" ("workspace_id" TEXT NOT NULL REFERENCES workspaces (id) ON DELETE CASCADE, "relative_path" TEXT NOT NULL, "source_json" TEXT NOT NULL, PRIMARY KEY ("workspace_id", "relative_path"));
CREATE TABLE "workspaces" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "environment_id" TEXT NOT NULL, "deleting" INTEGER NOT NULL DEFAULT 0 CHECK ("deleting" IN (0, 1)), "created_at" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE INDEX idx_agent_runs_conversation ON agent_runs (conversation_id, status);
CREATE INDEX idx_conversations_pinned_updated ON conversations (pinned DESC, updated_at DESC);
CREATE INDEX idx_memory_scope ON memory_entries (assistant_id, enabled, updated_at DESC);
CREATE INDEX idx_messages_conversation ON messages (conversation_id, created_at);
CREATE INDEX idx_messages_parent ON messages (parent_id);
CREATE INDEX idx_messages_run ON messages (run_id);
CREATE INDEX idx_model_requests_conversation ON model_requests (conversation_id, created_at DESC);
CREATE INDEX idx_model_requests_run ON model_requests (run_id, purpose, status);
CREATE INDEX idx_model_requests_summary ON model_requests (summary_job_id);
CREATE INDEX idx_plans_conversation ON agent_plans (conversation_id, created_at DESC);
CREATE INDEX idx_summaries_conversation ON context_summaries (conversation_id, created_at DESC);
CREATE INDEX idx_tool_calls_created ON tool_calls (created_at);
CREATE INDEX idx_tool_calls_run ON tool_calls (run_id);
CREATE INDEX idx_tool_calls_status ON tool_calls (status);
PRAGMA user_version = 8;
